import { defineConfig, devices } from '@playwright/test'

/**
 * @see https://playwright.dev/docs/test-configuration
 */
export default defineConfig({
  testDir: './tests/e2e',
  /* Run tests in files in parallel */
  fullyParallel: true,
  /* Fail the build on CI if you accidentally left test.only in the source code. */
  forbidOnly: !!process.env.CI,
  /* Retry on CI only */
  retries: process.env.CI ? 2 : 0,
  /* Opt out of parallel tests on CI. */
  workers: process.env.CI ? 1 : undefined,
  /* Reporter to use. See https://playwright.dev/docs/test-reporters */
  reporter: 'html',
  /* Shared settings for all the projects below. See https://playwright.dev/docs/api/class-testoptions. */
  use: {
    /* Base URL to use in actions like `await page.goto('/')`. */
    baseURL: 'http://localhost:5176',
    /* Collect trace when retrying the failed test. See https://playwright.dev/docs/trace-viewer */
    trace: 'on-first-retry',
    /* Set global timeout for actions like waitForSelector to 3 seconds */
    actionTimeout: 3000,
  },

  /* Configure projects for major browsers */
  projects: [
    // Setup project
    { name: 'setup', testMatch: /.*\.setup\.ts/ },


    // Tests that require authentication
    {
      name: 'chromium',
      use: { 
        ...devices['Desktop Chrome'],
        storageState: 'tests/.auth/user.json',
      },
      dependencies: ['setup'],
    },

    {
      name: 'firefox',
      use: { 
        ...devices['Desktop Firefox'],
        storageState: 'tests/.auth/user.json',
      },
      dependencies: ['setup'],
    },

    {
      name: 'webkit',
      use: { 
        ...devices['Desktop Safari'],
        storageState: 'tests/.auth/user.json',
      },
      dependencies: ['setup'],
    },

    /* Test against mobile viewports. */
    {
      name: 'Mobile Chrome',
      use: { 
        ...devices['Pixel 5'],
        storageState: 'tests/.auth/user.json',
      },
      dependencies: ['setup'],
    },
    {
      name: 'Mobile Safari',
      use: { 
        ...devices['iPhone 12'],
        storageState: 'tests/.auth/user.json',
      },
      dependencies: ['setup'],
    },

    /* Test against branded browsers. */
    // {
    //   name: 'Microsoft Edge',
    //   use: { ...devices['Desktop Edge'], channel: 'msedge' },
    // },
    // {
    //   name: 'Google Chrome',
    //   use: { ...devices['Desktop Chrome'], channel: 'chrome' },
    // },
  ],

  /* Run your local dev server before starting the tests */
  webServer: {
    command: 'npm run dev -- --port 5176',
    url: 'http://localhost:5176',
    reuseExistingServer: !process.env.CI,
  },
})

import { test as setup, expect } from '@playwright/test'

const authFile = 'tests/.auth/user.json'

// Test user credentials
const TEST_USER = {
  email: 'test@betterpack.dev', 
  password: 'testpassword123'
}

setup('authenticate', async ({ page }) => {
  console.log('Starting authentication setup...')

  // Navigate to login page
  await page.goto('/login')
  await page.waitForLoadState('domcontentloaded')

  // Wait for the login form to be visible
  await page.waitForSelector('#email')

  console.log('Login form found, filling credentials...')

  // Fill in credentials
  await page.fill('#email', TEST_USER.email)
  await page.fill('#password', TEST_USER.password)

  // Click sign in button
  await page.click('button[type="submit"]')

  // Wait for navigation - either to dashboard or back to login (if user doesn't exist)
  await page.waitForTimeout(2000)

  const currentUrl = page.url()
  console.log('Current URL after login attempt:', currentUrl)

  if (currentUrl.includes('/login')) {
    console.log('Login failed, trying signup...')

    // Go to signup page
    await page.click('a[href="/signup"], text="Sign up"')
    await page.waitForSelector('#email')

    // Fill signup form
    await page.fill('#email', TEST_USER.email)
    await page.fill('#password', TEST_USER.password)

    // Look for confirm password field
    const confirmPasswordField = page.locator('#confirmPassword, #confirm-password, input[placeholder*="confirm"], input[placeholder*="Confirm"]')
    if (await confirmPasswordField.isVisible()) {
      await confirmPasswordField.fill(TEST_USER.password)
    }

    await page.click('button[type="submit"]')
    await page.waitForTimeout(3000)
  }

  // Should now be logged in - check for dashboard or gear page
  const finalUrl = page.url()
  console.log('Final URL:', finalUrl)

  if (finalUrl.includes('/dashboard') || finalUrl.includes('/gear')) {
    console.log('Authentication successful!')

    // Save signed-in state to file
    await page.context().storageState({ path: authFile })
    console.log('Authentication state saved to:', authFile)
  } else {
    // Try to navigate to dashboard to verify auth worked
    await page.goto('/dashboard')
    await page.waitForTimeout(2000)

    const dashboardUrl = page.url()
    if (!dashboardUrl.includes('/login')) {
      console.log('Auth successful - can access dashboard')
      await page.context().storageState({ path: authFile })
    } else {
      throw new Error('Authentication failed - still being redirected to login')
    }
  }
})

import { test, expect } from '@playwright/test'

// E2E tests focus on user journeys and critical paths
// They test the full stack integration without mocking
// Note: These are basic smoke tests - full E2E tests will be added as features are built

test.describe('Basic Application Tests', () => {
  test('should load without crashing', async ({ page }) => {
    // Navigate to the app
    await page.goto('/')

    // Wait for page to be ready
    await page.waitForLoadState('domcontentloaded')

    // Verify the page has loaded (has a title)
    const title = await page.title()
    expect(title).toBeTruthy() // Should have some title

    // Verify no critical JS errors that prevent basic rendering
    // This is a basic smoke test to ensure the app starts up
    const html = await page.locator('html').innerHTML()
    expect(html.length).toBeGreaterThan(100) // Should have substantial content
  })
})

