import { test, expect } from '@playwright/test'

// Basic smoke tests that don't require authentication
// These can run in CI without Supabase credentials

test.describe('Smoke Tests', () => {
  test('app loads without crashing', async ({ page }) => {
    await page.goto('/')
    await page.waitForLoadState('domcontentloaded')

    // Should have a title
    const title = await page.title()
    expect(title).toBeTruthy()

    // Should render substantial content
    const html = await page.locator('html').innerHTML()
    expect(html.length).toBeGreaterThan(100)

    // Check for no critical JavaScript errors
    const errorLogs: string[] = []
    page.on('console', msg => {
      if (msg.type() === 'error') {
        errorLogs.push(msg.text())
      }
    })

    await page.waitForTimeout(1000) // Give time for any JS errors to surface

    // Filter out common non-critical errors
    const criticalErrors = errorLogs.filter(error => 
      !error.includes('favicon') && 
      !error.includes('sw.js') &&
      !error.includes('Failed to register')
    )

    expect(criticalErrors).toHaveLength(0)
  })

  test('navigation works', async ({ page }) => {
    await page.goto('/')
    await page.waitForLoadState('domcontentloaded')

    // Look for navigation elements (login/signup links should be present)
    const loginLink = page.locator('a[href="/login"], text="Login", text="Sign In"')
    const signupLink = page.locator('a[href="/signup"], text="Sign Up", text="Register"')

    // At least one of these should be visible on the landing page
    const hasAuthLinks = (await loginLink.count()) > 0 || (await signupLink.count()) > 0
    expect(hasAuthLinks).toBe(true)
  })

  test('responsive design works', async ({ page }) => {
    // Test mobile viewport
    await page.setViewportSize({ width: 375, height: 667 })
    await page.goto('/')
    await page.waitForLoadState('domcontentloaded')

    // Check that content is properly responsive
    const body = page.locator('body')
    const boundingBox = await body.boundingBox()

    expect(boundingBox).toBeTruthy()
    expect(boundingBox!.width).toBeLessThanOrEqual(375)

    // Test desktop viewport
    await page.setViewportSize({ width: 1920, height: 1080 })
    await page.goto('/')
    await page.waitForLoadState('domcontentloaded')

    const desktopBoundingBox = await body.boundingBox()
    expect(desktopBoundingBox).toBeTruthy()
  })
})

