import { test, expect } from '@playwright/test'

test.describe('GearForm Integration Tests', () => {
  test.beforeEach(async ({ page }) => {
    // Navigate to the gear closet page where the forms are actually used
    await page.goto('/gear')
    await page.waitForLoadState('domcontentloaded')

    // Wait for the page to fully load - should be authenticated now
    await page.waitForSelector('h1, [data-testid="gear-closet"], .max-w-7xl')
  })

  test.describe('Add Gear Form', () => {
    test('should open add gear form and display required fields', async ({ page }) => {
      // Look for the floating add button (should be a button with a plus icon)
      const addButton = page.locator('button').filter({ hasText: '' }).filter({ has: page.locator('svg') })
      await expect(addButton.first()).toBeVisible()
      await addButton.first().click()

      // Wait for the form to appear (might be in a modal/drawer)
      const form = page.locator('[data-gear-form]')
      await expect(form).toBeVisible()

      // Test that required fields are visible and in correct order
      const nameField = form.locator('#name')
      const weightField = form.locator('#weight')

      await expect(nameField).toBeVisible()
      await expect(weightField).toBeVisible()

      // Check that both fields are marked as required
      await expect(nameField).toHaveAttribute('required')
      await expect(weightField).toHaveAttribute('required')

      // Check labels have required asterisks
      const nameLabel = form.locator('label[for="name"]')
      const weightLabel = form.locator('label[for="weight"]')

      await expect(nameLabel).toContainText('*')
      await expect(weightLabel).toContainText('*')
    })

    test('should show Name and Weight fields side by side on desktop', async ({ page, isMobile }) => {
      if (isMobile) {
        test.skip('Skipping desktop layout test on mobile')
      }

      const form = page.locator('[data-gear-form]')
      const nameField = form.locator('#name')
      const weightField = form.locator('#weight')

      // Get bounding boxes to check layout
      const nameBox = await nameField.boundingBox()
      const weightBox = await weightField.boundingBox()

      // On desktop, fields should be side by side (same approximate Y position)
      expect(Math.abs((nameBox?.y || 0) - (weightBox?.y || 0))).toBeLessThan(50)

      // Name should be to the left of weight
      expect(nameBox?.x).toBeLessThan(weightBox?.x || 0)
    })

    test('should show Category and Options side by side on desktop', async ({ page, isMobile }) => {
      if (isMobile) {
        test.skip('Skipping desktop layout test on mobile')
      }

      const form = page.locator('[data-gear-form]')

      // Find the category select button and options section
      const categorySelect = form.locator('[role="button"]').filter({ hasText: 'Other' }).first()
      const optionsSection = form.locator('text=Options').locator('..')

      await expect(categorySelect).toBeVisible()
      await expect(optionsSection).toBeVisible()

      const categoryBox = await categorySelect.boundingBox()
      const optionsBox = await optionsSection.boundingBox()

      // Should be roughly on the same line
      if (categoryBox && optionsBox) {
        expect(Math.abs(categoryBox.y - optionsBox.y)).toBeLessThan(50)
      }
    })

    test('should display weight unit conversions', async ({ page }) => {
      const form = page.locator('[data-gear-form]')
      const weightField = form.locator('#weight')

      // Enter a weight value
      await weightField.fill('16')
      await weightField.blur()

      // Look for weight conversion preview
      const conversionText = form.locator('text=/(\\(.*g.*oz.*lb.*kg.*\\))/i').first()

      // Should show conversions after entering weight
      await expect(conversionText).toBeVisible({ timeout: 2000 })
    })

    test('should have image upload in advanced section', async ({ page }) => {
      const form = page.locator('[data-gear-form]')

      // Initially, image upload should not be visible
      const imageUpload = form.locator('[data-testid="image-upload"]')

      // If it's in advanced section, it won't be visible initially
      // Click advanced options toggle if it exists
      const advancedToggle = form.locator('button:has-text("Show advanced options")')

      if (await advancedToggle.isVisible()) {
        await advancedToggle.click()

        // Now image upload should be visible
        await expect(imageUpload).toBeVisible({ timeout: 2000 })
      }
    })

    test('should show all basic fields without advanced toggle', async ({ page }) => {
      const form = page.locator('[data-gear-form]')

      // Core fields should always be visible
      await expect(form.locator('#name')).toBeVisible()
      await expect(form.locator('#weight')).toBeVisible()
      await expect(form.locator('#brand')).toBeVisible()
      await expect(form.locator('#model')).toBeVisible()
      await expect(form.getByRole('button', { name: 'Other' })).toBeVisible()

      // Options checkboxes
      await expect(form.locator('text=Worn')).toBeVisible()
      await expect(form.locator('text=Consumable')).toBeVisible()
    })

    test('should validate required fields', async ({ page }) => {
      const form = page.locator('[data-gear-form]')
      const submitButton = form.locator('button[type="submit"]')

      // Try to submit without filling required fields
      await submitButton.click()

      // Form should prevent submission (name field should be focused or show validation)
      const nameField = form.locator('#name')
      await expect(nameField).toBeFocused()
    })

    test('should show validation error for invalid weight', async ({ page }) => {
      const form = page.locator('[data-gear-form]')
      const nameField = form.locator('#name')
      const weightField = form.locator('#weight')
      const submitButton = form.locator('button[type="submit"]')

      // Fill name but invalid weight
      await nameField.fill('Test Item')
      await weightField.fill('-5')

      await submitButton.click()

      // Should show weight error
      const errorMessage = form.locator('text="Please enter a valid weight"')
      await expect(errorMessage).toBeVisible({ timeout: 2000 })
    })
  })

  test.describe('Responsive Behavior', () => {
    test('should stack fields vertically on mobile', async ({ page, isMobile }) => {
      if (!isMobile) {
        // Set mobile viewport
        await page.setViewportSize({ width: 375, height: 667 })
      }

      const form = page.locator('[data-gear-form]')
      const nameField = form.locator('#name')
      const weightField = form.locator('#weight')

      const nameBox = await nameField.boundingBox()
      const weightBox = await weightField.boundingBox()

      // On mobile, weight should be below name (higher Y position)
      if (nameBox && weightBox) {
        expect(weightBox.y).toBeGreaterThan(nameBox.y + 20)
      }
    })

    test('should have proper touch targets on mobile', async ({ page, isMobile }) => {
      if (!isMobile) {
        await page.setViewportSize({ width: 375, height: 667 })
      }

      const form = page.locator('[data-gear-form]')

      // Check that input fields have minimum touch target height
      const inputs = form.locator('input, button, [role="button"]')
      const inputCount = await inputs.count()

      for (let i = 0; i < inputCount; i++) {
        const input = inputs.nth(i)
        if (await input.isVisible()) {
          const box = await input.boundingBox()
          if (box) {
            // Should be at least 44px tall for good touch target
            expect(box.height).toBeGreaterThanOrEqual(40)
          }
        }
      }
    })
  })

  test.describe('Smart Features', () => {
    test('should suggest category based on item name', async ({ page }) => {
      const form = page.locator('[data-gear-form]')
      const nameField = form.locator('#name')

      // Type a name that should trigger category suggestion
      await nameField.fill('tent')

      // Wait a moment for the suggestion logic
      await page.waitForTimeout(500)

      // Check if category was auto-selected to Shelter
      const categoryButton = form.locator('[role="button"]').filter({ hasText: 'Shelter' }).first()

      // The category might be auto-selected
      await expect(categoryButton).toBeVisible({ timeout: 2000 })
    })

    test('should parse weight input with units', async ({ page }) => {
      const form = page.locator('[data-gear-form]')
      const weightField = form.locator('#weight')

      // Enter weight with unit
      await weightField.fill('12 oz')
      await weightField.blur()

      // Should parse and show conversion
      await expect(weightField).toHaveValue('12')

      // Unit selector should be set to oz
      const unitSelect = form.locator('select').or(form.locator('[role="button"]')).filter({ hasText: 'oz' })
      await expect(unitSelect).toBeVisible({ timeout: 2000 })
    })

    test('should support keyboard shortcuts', async ({ page }) => {
      const form = page.locator('[data-gear-form]')
      const nameField = form.locator('#name')
      const weightField = form.locator('#weight')

      // Fill form
      await nameField.fill('Test Item')
      await weightField.fill('100')

      // Try Cmd+Enter (or Ctrl+Enter) to submit
      const modifier = process.platform === 'darwin' ? 'Meta' : 'Control'
      await page.keyboard.press(`${modifier}+Enter`)

      // Form should be submitted (this depends on the onSubmit implementation)
      // We'll just verify the keyboard event was handled
      await page.waitForTimeout(100)
    })
  })

  test.describe('Advanced Options', () => {
    test('should toggle advanced options visibility', async ({ page }) => {
      const form = page.locator('[data-gear-form]')
      const advancedToggle = form.locator('button:has-text("Show advanced options")')

      if (await advancedToggle.isVisible()) {
        // Initially advanced options should be hidden
        const quantityField = form.locator('#quantity')
        await expect(quantityField).toBeHidden()

        // Click to show advanced options
        await advancedToggle.click()

        // Now advanced fields should be visible
        await expect(quantityField).toBeVisible()
        await expect(form.locator('#price')).toBeVisible()
        await expect(form.locator('#description')).toBeVisible()
        await expect(form.locator('#notes')).toBeVisible()

        // Toggle text should change
        await expect(form.locator('button:has-text("Hide advanced options")')).toBeVisible()
      }
    })

    test('should have proper layout for advanced fields', async ({ page, isMobile }) => {
      const form = page.locator('[data-gear-form]')
      const advancedToggle = form.locator('button:has-text("Show advanced options")')

      if (await advancedToggle.isVisible()) {
        await advancedToggle.click()

        if (!isMobile) {
          // On desktop, quantity and price should be side by side
          const quantityField = form.locator('#quantity')
          const priceField = form.locator('#price')

          const quantityBox = await quantityField.boundingBox()
          const priceBox = await priceField.boundingBox()

          if (quantityBox && priceBox) {
            expect(Math.abs(quantityBox.y - priceBox.y)).toBeLessThan(50)
            expect(quantityBox.x).toBeLessThan(priceBox.x)
          }
        }

        // Description and Notes should be full width
        const descriptionField = form.locator('#description')
        const notesField = form.locator('#notes')

        await expect(descriptionField).toBeVisible()
        await expect(notesField).toBeVisible()
      }
    })
  })
})

