import { test, expect } from '@playwright/test'

// Basic authenticated user journeys
// These tests require authentication and will only run when Supabase credentials are available

test.describe('Authenticated Application Tests', () => {
  test.beforeEach(async ({ page }) => {
    // These tests require authentication - skip if not available
    if (!process.env.VITE_SUPABASE_URL || !process.env.VITE_SUPABASE_ANON_KEY) {
      test.skip('Skipping authenticated tests - no Supabase credentials available')
    }

    // Navigate to gear page (should be authenticated via storage state)
    await page.goto('/gear')
    await page.waitForLoadState('domcontentloaded')
  })

  test('should access gear page when authenticated', async ({ page }) => {
    // Should be on gear page, not redirected to login
    expect(page.url()).toContain('/gear')

    // Should have gear-related content
