const TEST_USER = {
  email: 'test@betterpack.dev', 
  password: 'testpassword123'
}

setup('authenticate', async ({ page }) => {
  // Skip auth setup if we don't have Supabase credentials
  if (!process.env.VITE_SUPABASE_URL || !process.env.VITE_SUPABASE_ANON_KEY) {
    console.log('Skipping auth setup - no Supabase credentials available')
    return
  }

  console.log('Starting authentication setup...')

  try {
    // Navigate to login page with timeout
    await page.goto('/login', { timeout: 10000 })
    await page.waitForLoadState('domcontentloaded')

    // Wait for the login form to be visible with timeout
    await page.waitForSelector('#email', { timeout: 5000 })

    console.log('Login form found, filling credentials...')

    // Fill in credentials
    await page.fill('#email', TEST_USER.email)
    await page.fill('#password', TEST_USER.password)

    // Click sign in button
    await page.click('button[type="submit"]')

    // Wait for navigation with proper timeout
    await page.waitForTimeout(3000)

    const currentUrl = page.url()
    console.log('Current URL after login attempt:', currentUrl)

    if (currentUrl.includes('/login')) {
      console.log('Login failed, trying signup...')

      // Go to signup page
      const signupLink = page.locator('a[href="/signup"], text="Sign up"')
      if (await signupLink.isVisible()) {
        await signupLink.click()
        await page.waitForSelector('#email', { timeout: 5000 })

        // Fill signup form
        await page.fill('#email', TEST_USER.email)
        await page.fill('#password', TEST_USER.password)

        // Look for confirm password field
        const confirmPasswordField = page.locator('#confirmPassword, #confirm-password, input[placeholder*="confirm"], input[placeholder*="Confirm"]')
        if (await confirmPasswordField.isVisible()) {
          await confirmPasswordField.fill(TEST_USER.password)
        }

        await page.click('button[type="submit"]')
        await page.waitForTimeout(5000)
      }
    }

    // Should now be logged in - check for dashboard or gear page
    const finalUrl = page.url()
    console.log('Final URL:', finalUrl)

    if (finalUrl.includes('/dashboard') || finalUrl.includes('/gear') || !finalUrl.includes('/login')) {
      console.log('Authentication successful!')

      // Save signed-in state to file
      await page.context().storageState({ path: authFile })
      console.log('Authentication state saved to:', authFile)
    } else {
      // Try to navigate to dashboard to verify auth worked
      await page.goto('/dashboard', { timeout: 30000 })
      await page.waitForTimeout(3000)

      const dashboardUrl = page.url()
      if (!dashboardUrl.includes('/login')) {
        console.log('Auth successful - can access dashboard')
        await page.context().storageState({ path: authFile })
      } else {
        console.warn('Authentication may have failed - still being redirected to login')
        // Don't throw error in CI, just warn
        if (!process.env.CI) {
          throw new Error('Authentication failed - still being redirected to login')
        }
      }
    }
  } catch (error) {
    console.error('Auth setup failed:', error)
    if (!process.env.CI) {
      throw error
    }
    // In CI, don't fail the entire test suite if auth setup fails
    console.log('Continuing without authentication in CI environment')
  }
})

