import { createClient } from '@supabase/supabase-js'

const authFile = 'tests/.auth/user.json'

// Test user credentials - use timestamp to ensure uniqueness
const TEST_USER = {
  email: `test-${Date.now()}@betterpack.dev`, 
  password: 'TestPassword123!'
}

async function testSupabaseConnection() {
  try {
    const supabaseUrl = process.env.VITE_SUPABASE_URL!
    const supabaseKey = process.env.VITE_SUPABASE_ANON_KEY!

    const supabase = createClient(supabaseUrl, supabaseKey)

    // Test connection with a simple query
    const { error } = await supabase.from('gear_items').select('count').limit(1)

    if (error && !error.message.includes('JWT')) {
      throw new Error(`Supabase connection failed: ${error.message}`)
    }

    return true
  } catch (error) {
    console.error('Supabase connection test failed:', error)
    return false
  }
}

setup('authenticate', async ({ page }) => {
  // Skip auth setup if we don't have Supabase credentials
  if (!process.env.VITE_SUPABASE_URL || !process.env.VITE_SUPABASE_ANON_KEY) {
