    await page.goto('/signup', { timeout: 10000 })
    await page.waitForLoadState('domcontentloaded')

    // Wait for the signup form to be visible
    await page.waitForSelector('#email', { timeout: 5000 })

    // Fill signup form
    await page.fill('#email', TEST_USER.email)
    await page.fill('#password', TEST_USER.password)

    // Look for confirm password field and fill it
    const confirmPasswordField = page.locator('#confirmPassword, #confirm-password, input[placeholder*="confirm"], input[placeholder*="Confirm"]')
    if (await confirmPasswordField.isVisible()) {
      await confirmPasswordField.fill(TEST_USER.password)
    }

    // Submit signup form
    await page.click('button[type="submit"]')

    // Wait for either success or error
    await page.waitForTimeout(5000)

    const currentUrl = page.url()
    console.log('📍 Current URL after signup:', currentUrl)

    if (currentUrl.includes('/login')) {
      // Sometimes redirects to login after signup, try logging in
      console.log('🔄 Redirected to login, attempting to sign in...')

      await page.waitForSelector('#email', { timeout: 5000 })
      await page.fill('#email', TEST_USER.email)
      await page.fill('#password', TEST_USER.password)
      await page.click('button[type="submit"]')
      await page.waitForTimeout(5000)
    }

    // Verify we're authenticated by trying to access a protected route
    await page.goto('/gear', { timeout: 10000 })
    await page.waitForTimeout(3000)

    const finalUrl = page.url()
    console.log('🎯 Final URL after auth flow:', finalUrl)

    if (finalUrl.includes('/gear') && !finalUrl.includes('/login')) {
      console.log('✅ Authentication successful! Accessing /gear page')

      // Save authenticated state
      await page.context().storageState({ path: authFile })
      console.log('💾 Authentication state saved to:', authFile)
    } else if (!finalUrl.includes('/login')) {
      // Not on login page, probably authenticated
      console.log('✅ Authentication appears successful (not on login page)')
      await page.context().storageState({ path: authFile })
    } else {
      throw new Error('Authentication failed - still being redirected to login page')
    }

  } catch (error) {
    console.error('❌ Auth setup failed:', error)
    if (process.env.CI) {
      // In CI, don't fail the test suite for auth issues
      console.log('⚠️  Continuing without authentication in CI environment')
      return
    }
    throw error
  }
})

