import { test, expect } from '@playwright/test'

test.describe('GearForm Integration Tests', () => {
  test.beforeEach(async ({ page }) => {
    // Navigate to the gear closet page where the forms are actually used
    await page.goto('/gear')
    await page.waitForLoadState('domcontentloaded')

    // Wait for the page to fully load - should be authenticated now
    await page.waitForSelector('h1, [data-testid="gear-closet"], .max-w-7xl')
  })

  test.describe('Add Gear Form', () => {
    test('should open add gear form and display required fields', async ({ page }) => {
      // Look for the floating add button (should be a button with a plus icon)
      const addButton = page.locator('button').filter({ hasText: '' }).filter({ has: page.locator('svg') })
