import { test, expect } from '@playwright/test'

// Basic tests to verify authenticated access to gear functionality
test.describe('Gear Page Basic Tests', () => {
  test.beforeEach(async ({ page }) => {
    // Skip if no Supabase credentials
    if (!process.env.VITE_SUPABASE_URL || !process.env.VITE_SUPABASE_ANON_KEY) {
      test.skip('Skipping authenticated tests - no Supabase credentials available')
    }

    // Navigate to gear page
    await page.goto('/gear')
    await page.waitForLoadState('domcontentloaded')
  })

  test('should successfully access gear page when authenticated', async ({ page }) => {
    // Should not be redirected to login
    expect(page.url()).toContain('/gear')
    expect(page.url()).not.toContain('/login')

    // Page should have loaded content
    const title = await page.title()
    expect(title).toBeTruthy()
    expect(title).toContain('BetterPack')
  })

  test('should show gear-related interface elements', async ({ page }) => {
    // Wait for page to be interactive
    await page.waitForTimeout(2000)

    // Look for any gear-related UI elements
    const gearElements = await Promise.all([
      page.locator('h1, h2, h3').filter({ hasText: /gear|closet|equipment/i }).count(),
      page.locator('button').filter({ hasText: /add|new|create/i }).count(),
      page.locator('input[placeholder*="search"]').count(),
      page.locator('[data-testid*="gear"]').count(),
      page.locator('.gear, [class*="gear"]').count()
    ])

    const hasGearElements = gearElements.some(count => count > 0)
    expect(hasGearElements).toBe(true)
  })

  test('should be responsive on mobile', async ({ page }) => {
    // Test mobile viewport
    await page.setViewportSize({ width: 375, height: 667 })
    await page.reload()
    await page.waitForLoadState('domcontentloaded')

    // Should still be on gear page
    expect(page.url()).toContain('/gear')

    // Should have mobile-appropriate layout
    const body = page.locator('body')
    const box = await body.boundingBox()
    expect(box?.width).toBeLessThanOrEqual(375)
  })
})

