import { test, expect } from '@playwright/test'

test('debug login page', async ({ page }) => {
  await page.goto('/login')
  await page.waitForLoadState('domcontentloaded')

  // Wait for React to render
  await page.waitForTimeout(2000)

  // Take a screenshot to see what's on the page
  await page.screenshot({ path: 'login-page.png' })

  // Log the current URL
  console.log('Current URL:', page.url())

  // Look for login form or any form elements
  const forms = page.locator('form')
  const formCount = await forms.count()
  console.log('Forms found:', formCount)

  // Look for any input elements
  const allInputs = page.locator('input')
  const inputCount = await allInputs.count()
  console.log('Total inputs found:', inputCount)

  if (inputCount > 0) {
    for (let i = 0; i < inputCount; i++) {
      const input = allInputs.nth(i)
      const id = await input.getAttribute('id')
      const type = await input.getAttribute('type')
      const placeholder = await input.getAttribute('placeholder')
      const name = await input.getAttribute('name')
      console.log(`Input ${i}: id=${id}, type=${type}, name=${name}, placeholder=${placeholder}`)
    }
  }

  // Look for text that suggests login
  const loginText = page.locator('text="Sign in"')
  const loginTextVisible = await loginText.isVisible().catch(() => false)
  console.log('Sign in text found:', loginTextVisible)

  // Check if we're redirected to login or somewhere else
  const pageTitle = await page.title()
  console.log('Page title:', pageTitle)

  // Look for any error messages or loading states
  const errorText = page.locator('[role="alert"], .error, .alert')
  const errorCount = await errorText.count()
  console.log('Error elements found:', errorCount)
})

